def _adjust_sources(fs, plot_props, config_dir):
    new_plot_props = deepcopy(plot_props)

    # Process y-axis paths
    old_y = new_plot_props.pop("y", {})
    new_y = {}
    if isinstance(old_y, dict):
        for filepath, val in old_y.items():
            new_y[_normpath(fs.join(config_dir, filepath))] = val
    else:
        # If y is not a dict, keep it as is
        new_y = old_y
    new_plot_props["y"] = new_y

    # Process x-axis paths
    old_x = new_plot_props.pop("x", {}) if "x" in new_plot_props else {}
    new_x = {}
    if isinstance(old_x, dict):
        for filepath, val in old_x.items():
            new_x[_normpath(fs.join(config_dir, filepath))] = val
    else:
        # If x is not a dict, keep it as is
        new_x = old_x
    new_plot_props["x"] = new_x

    return new_plot_props
